module benchmark/solution

func fizzBuzz(n: int) -> string =
  if n % 15 == 0 then "FizzBuzz"
  else if n % 3 == 0 then "Fizz"
  else if n % 5 == 0 then "Buzz"
  else show(n)

func printFizzBuzz(n: int) -> () ! {IO} =
  if n > 100 then ()
  else {
    println(fizzBuzz(n));
    printFizzBuzz(n + 1)
  }

export func main() -> () ! {IO} = printFizzBuzz(1)
